; The Old Quarry, under the Mirewood. In up the ramp from the mouth at the bottom into the upper
; cut, the quarrymen's store off it to the west and the tar coming up in the bay to the east. The
; first roots are across the way north out of the cut, at its west end, and Sera parts them; past
; them the roots have broken the floor of the second cut up, and the second roots are across the
; way north out of that. Then the passage along the top, where the black's come up through the
; floor, and down it to where the courier lies, and the Thornmother's den, with the black crystal
; spike against its back wall. Lit by the daylight down the ramp, the fungus that glows, the
; crystal coming through the walls, and the spike itself.

[map]
id = mirewood-quarry
name = The Old Quarry
tileset = quarry
size = 36 32
dark = yes
ambient = 0.1
music = Underground

[legend]
, = floor
s = floor-shadow
v = black-vein-floor
r = root-floor
~ = tar-seep
= = ramp
# = wall-top
F = wall-face
R = wall-roots
C = wall-crystal
B = wall-base
x = rubble
g = gravel
o = roots
* = shards
f = fungus
t = tools

